def choose_move(observation):
    # Defensive defaults
    x = None
    y = None

    # Attempt to read a positional suggestion if present
    if isinstance(observation, dict):
        x = observation.get('x')
        y = observation.get('y')
        # Some environments may encode as 'player' with coords
        if x is None or y is None:
            p = observation.get('player')
            if isinstance(p, dict):
                x = p.get('x', x)
                y = p.get('y', y)

        # Fallback: directional hints
        if x is None:
            dx_hint = observation.get('dx')
            if isinstance(dx_hint, int):
                x = dx_hint
        if y is None:
            dy_hint = observation.get('dy')
            if isinstance(dy_hint, int):
                y = dy_hint

    # Normalize to valid moves
    if x is None:
        x = 0
    if y is None:
        y = 0

    # Clamp to -1, 0, 1
    def clamp01(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    dx = clamp01(int(x))
    dy = clamp01(int(y))

    return [dx, dy]

